raw_response:
VAR
    Overload_Timer : TON;
END_VAR

// Check if motor current exceeds the 125% threshold (51.9 A) while running
// Using the available Overload_Timer for a debounce/trip delay of 3 seconds
Over_Temp_Trip_Cond := Motor_Current > 51.9 AND Motor_Running;

Overload_Timer(IN := Over_Timer_Trip_Cond,
               PT := T#3S);

// Set Overload_Alarm when timer reaches preset
IF Overload_Timer.Q THEN
    Overload_Alarm := TRUE;
END_IF

// Reset alarm and stop motor on fault reset or high current trip
IF Overload_Timer.Q THEN
    Motor_Stop := TRUE;
END_IF

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
    Motor_Stop := FALSE;
END_IF

